function validate([heights]) {
  if (!Array.isArray(heights) || heights.length < 1 || heights.length > 1000) return 'heights needs 1 to 1000 values.';
  if (heights.some(h => !Number.isInteger(h) || h < 1 || h > 1000000000)) return 'Each height is an integer from 1 to 10^9.';
  return null;
}

