function maximumSumOfHeights(heights) {
  const n = heights.length;
  let best = 0;
  for (let peak = 0; peak < n; peak++) {
    let sum = heights[peak];
    let cap = heights[peak];
    for (let left = peak - 1; left >= 0; left--) {
      cap = Math.min(cap, heights[left]);
      sum += cap;
    }
    cap = heights[peak];
    for (let right = peak + 1; right < n; right++) {
      cap = Math.min(cap, heights[right]);
      sum += cap;
    }
    best = Math.max(best, sum);
  }
  return best;
}

