function maximumSumOfHeights(heights) {
  // With the peak at p, tower j can keep at most the smallest height between j and p.
  const n = heights.length;
  let answer = 0;
  for (let p = 0; p < n; p++) {
    let total = 0;
    for (let j = 0; j < n; j++) {
      const range = heights.slice(Math.min(j, p), Math.max(j, p) + 1);
      total += Math.min(...range);
    }
    if (total > answer) answer = total;
  }
  return answer;
}

